package com.expensetracker.util;

import java.util.List;

/**
 * Charts drawn as INLINE SVG generated by pure Java — no JavaScript,
 * no chart library (per the project constraints). Colours come from a
 * fixed editorial palette so charts match the site design.
 */
public final class Svg {

    private Svg() {
    }

    /** Muted editorial palette, cycled for many categories. */
    private static final String[] PALETTE = {
            "#1e5631", "#b98a2f", "#7a3b2e", "#2e5a7a", "#6b4d7a",
            "#3f6b4f", "#a35c2a", "#4a4a48", "#8a7a2e", "#2e7a6b"
    };

    /** One slice of a donut / one bar of a bar chart. */
    public record Slice(String label, double value) {
    }

    /**
     * Donut chart: category-wise breakdown. Each slice is an SVG circle
     * with a stroke-dasharray trick; a legend lists label + share %.
     */
    public static String donut(List<Slice> slices, int sizePx) {
        double total = slices.stream().mapToDouble(Slice::value).sum();
        if (total <= 0 || slices.isEmpty()) {
            return "<p class=\"muted\">No data to chart yet.</p>";
        }
        double radius = 70;
        double circumference = 2 * Math.PI * radius;
        StringBuilder sb = new StringBuilder();
        sb.append("<div class=\"chart-wrap\">");
        sb.append("<svg viewBox=\"0 0 180 180\" width=\"").append(sizePx)
          .append("\" height=\"").append(sizePx)
          .append("\" role=\"img\" aria-label=\"Category breakdown chart\">");

        double offset = 25; // start at 12 o'clock
        for (int i = 0; i < slices.size(); i++) {
            Slice s = slices.get(i);
            double frac = s.value() / total;
            double dash = frac * circumference;
            double gap = circumference - dash;
            String color = PALETTE[i % PALETTE.length];
            sb.append("<circle cx=\"90\" cy=\"90\" r=\"").append(radius)
              .append("\" fill=\"none\" stroke=\"").append(color)
              .append("\" stroke-width=\"26\" stroke-dasharray=\"")
              .append(String.format("%.2f %.2f", dash, gap))
              .append("\" stroke-dashoffset=\"").append(String.format("%.2f", offset))
              .append("\"><title>").append(Html.esc(s.label()))
              .append(": ").append(String.format("%.1f%%", frac * 100))
              .append("</title></circle>");
            offset -= dash; // move backwards around the circle
        }
        sb.append("</svg>");
        sb.append("<ul class=\"legend\">");
        for (int i = 0; i < slices.size(); i++) {
            Slice s = slices.get(i);
            sb.append("<li><span class=\"swatch\" style=\"background:")
              .append(PALETTE[i % PALETTE.length]).append("\"></span>")
              .append(Html.esc(s.label()))
              .append(" <span class=\"muted\">")
              .append(String.format("%.1f%%", s.value() / total * 100))
              .append("</span></li>");
        }
        sb.append("</ul></div>");
        return sb.toString();
    }

    /**
     * Grouped bar chart: monthly income vs expense trend.
     * Pure SVG rects + text; values on top of bars.
     */
    public static String bars(List<String> labels, List<Double> income,
                              List<Double> expense, int widthPx, int heightPx) {
        if (labels.isEmpty()) {
            return "<p class=\"muted\">No data to chart yet.</p>";
        }
        double max = 1.0;
        for (int i = 0; i < labels.size(); i++) {
            max = Math.max(max, Math.max(income.get(i), expense.get(i)));
        }
        // Round the axis headroom up so bars never touch the top edge.
        max = Math.ceil(max * 1.15);

        int n = labels.size();
        int padLeft = 8, padRight = 8, padTop = 26, padBottom = 30;
        int plotW = widthPx - padLeft - padRight;
        int plotH = heightPx - padTop - padBottom;
        double groupW = (double) plotW / n;
        double barW = Math.min(34, groupW * 0.32);

        StringBuilder sb = new StringBuilder();
        sb.append("<svg viewBox=\"0 0 ").append(widthPx).append(' ').append(heightPx)
          .append("\" width=\"100%\" role=\"img\" aria-label=\"Monthly income vs expense\">");

        // baseline
        int baseY = padTop + plotH;
        sb.append("<line x1=\"").append(padLeft).append("\" y1=\"").append(baseY)
          .append("\" x2=\"").append(widthPx - padRight).append("\" y2=\"").append(baseY)
          .append("\" stroke=\"var(--border)\" stroke-width=\"1\"/>");

        for (int i = 0; i < n; i++) {
            double cx = padLeft + groupW * i + groupW / 2;
            double inH = income.get(i) / max * plotH;
            double exH = expense.get(i) / max * plotH;

            // income bar (left, green)
            sb.append(bar(cx - barW - 2, baseY - inH, barW, inH, "#1e5631",
                    labels.get(i) + " income " + fmt(income.get(i))));
            // expense bar (right, amber)
            sb.append(bar(cx + 2, baseY - exH, barW, exH, "#b98a2f",
                    labels.get(i) + " expense " + fmt(expense.get(i))));

            // month label
            sb.append("<text x=\"").append(fmt(cx)).append("\" y=\"").append(baseY + 18)
              .append("\" text-anchor=\"middle\" class=\"svg-label\">")
              .append(Html.esc(labels.get(i))).append("</text>");
        }
        sb.append("</svg>");
        sb.append("""
                <div class="chart-key">
                  <span><span class="swatch" style="background:#1e5631"></span>Income</span>
                  <span><span class="swatch" style="background:#b98a2f"></span>Expense</span>
                </div>""");
        return sb.toString();
    }

    private static String bar(double x, double y, double w, double h, String color, String title) {
        if (h < 1) {
            h = 1; // keep zero values visible as a hairline
        }
        return "<rect x=\"" + fmt(x) + "\" y=\"" + fmt(y) + "\" width=\"" + fmt(w)
                + "\" height=\"" + fmt(h) + "\" rx=\"3\" fill=\"" + color
                + "\"><title>" + Html.esc(title) + "</title></rect>";
    }

    private static String fmt(double d) {
        return String.format("%.1f", d);
    }

    /** Simple horizontal progress bar (used for budget usage). */
    public static String progress(double percent) {
        double clamped = Math.min(100.0, Math.max(0.0, percent));
        String color = percent > 100 ? "#a83232" : percent > 80 ? "#b98a2f" : "#1e5631";
        return """
                <div class="progress" role="img" aria-label="%s%% of budget used">
                  <div class="progress-fill" style="width:%s%%;background:%s"></div>
                </div>
                """.formatted(String.format("%.1f", percent),
                String.format("%.1f", clamped), color);
    }
}
